// Classifica a saída do Motor de Performance para apresentação ao gestor.
// IMPORTANTE: esta etapa não pausa, escala ou altera campanhas.

// Limites iniciais de amostra. Ajustaremos após acumular dados reais.
const MIN_CONVERSAS = 2;
const MIN_CLIQUES_LINK = 20;

function numero(valor) {
  if (valor === undefined || valor === null || valor === '') return 0;
  if (typeof valor === 'number') return valor;

  let texto = String(valor).replace('R$', '').trim();

  if (texto.includes(',') && texto.includes('.')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else if (texto.includes(',')) {
    texto = texto.replace(',', '.');
  }

  return Number(texto) || 0;
}

function nomeDoObjeto(registro) {
  return registro['NOME ANUNCIO']
    || registro['ANUNCIO']
    || registro['NOME CONJUNTO']
    || registro['CONJUNTO']
    || registro['NOME CAMPANHA']
    || 'Sem nome';
}

function nivelDoObjeto(registro) {
  return registro['NIVEL ANALISE']
    || registro['NÍVEL ANÁLISE']
    || 'Não identificado';
}

function classificar(registro) {
  const score = numero(registro['SCORE TECNICO']);
  const conversas = numero(registro['CONVERSAS INICIADAS']);
  const cliquesLink = numero(registro['CLIQUES LINK']);

  // A amostra é considerada mínima quando já houve algum sinal de volume.
  const amostraSuficiente =
    conversas >= MIN_CONVERSAS ||
    cliquesLink >= MIN_CLIQUES_LINK;

  if (!amostraSuficiente) {
    return {
      classificacao: 'DADOS INSUFICIENTES',
      prioridade: 'BAIXA',
      ordem: 5,
      acao: 'Não tomar decisão ainda. Coletar mais dados.'
    };
  }

  if (score >= 70) {
    return {
      classificacao: 'DESTAQUE',
      prioridade: 'MÉDIA',
      ordem: 1,
      acao: 'Manter. É candidato a teste de escala quando o Motor de Decisão estiver ativo.'
    };
  }

  if (score >= 55) {
    return {
      classificacao: 'SAUDÁVEL',
      prioridade: 'BAIXA',
      ordem: 2,
      acao: 'Manter e continuar coletando dados.'
    };
  }

  if (score >= 40) {
    return {
      classificacao: 'OBSERVAR',
      prioridade: 'MÉDIA',
      ordem: 3,
      acao: 'Acompanhar custo, CTR de link e conversão antes de alterar.'
    };
  }

  return {
    classificacao: 'ATENÇÃO',
    prioridade: 'ALTA',
    ordem: 4,
    acao: 'Revisar criativo, público e oferta antes de aumentar investimento.'
  };
}

// Aceita tanto o resumo consolidado do Motor quanto uma lista direta de registros.
const entrada = items.length === 1 ? items[0].json : null;

if (entrada?.status_motor === 'SEM_DADOS_DIARIOS') {
  return [];
}

const registros = Array.isArray(entrada?.registros_performance)
  ? entrada.registros_performance
  : items.map(item => item.json);

if (!registros.length) return [];

const classificados = registros.map(registro => {
  const classe = classificar(registro);

  return {
    ...registro,
    'CLASSIFICACAO GESTOR': classe.classificacao,
    'PRIORIDADE GESTOR': classe.prioridade,
    'ORDEM GESTOR': classe.ordem,
    'ACAO SUGERIDA': classe.acao,
    'NOME OBJETO GESTOR': nomeDoObjeto(registro),
    'NIVEL OBJETO GESTOR': nivelDoObjeto(registro)
  };
});

// Mantém também os totais já calculados pelo Motor.
return [{
  json: {
    status_saida_gestor: 'OK',
    data_referencia: entrada?.data_referencia || classificados[0]['DATA REFERENCIA'] || '',
    investimento_total: entrada?.investimento_total ?? classificados.reduce((s, x) => s + numero(x.INVESTIMENTO), 0),
    conversas_iniciadas: entrada?.conversas_iniciadas ?? classificados.reduce((s, x) => s + numero(x['CONVERSAS INICIADAS']), 0),
    custo_medio_por_conversa: entrada?.custo_medio_por_conversa ?? null,
    score_tecnico_medio: entrada?.score_tecnico_medio ?? null,
    quantidade_registros: classificados.length,
    resultados_classificados: classificados
  }
}];

// Monta um briefing curto e legível para Telegram.
// A saída estruturada permanece disponível no campo painel_gestor.

function numero(valor) {
  const n = Number(valor);
  return Number.isFinite(n) ? n : 0;
}

function dinheiro(valor) {
  if (valor === null || valor === undefined || valor === '') return '—';
  return Number(valor).toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  });
}

function percentual(valor) {
  if (valor === null || valor === undefined || valor === '') return '—';
  return `${Number(valor).toFixed(2).replace('.', ',')}%`;
}

function linha(registro) {
  const nome = registro['NOME OBJETO GESTOR'];
  const nivel = registro['NIVEL OBJETO GESTOR'];
  const score = numero(registro['SCORE TECNICO']);
  const conversas = numero(registro['CONVERSAS INICIADAS']);
  const custo = registro['CUSTO CONVERSA CALCULADO'];
  const ctrLink = registro['CTR LINK'];

  return [
    `${nivel}: ${nome}`,
    `Score ${score} | ${conversas} conversas | ${dinheiro(custo)}/conversa | CTR link ${percentual(ctrLink)}`,
    `Ação: ${registro['ACAO SUGERIDA']}`
  ].join('\n');
}

const dados = $json;

if (dados.status_saida_gestor !== 'OK') {
  return [];
}

const registros = [...(dados.resultados_classificados || [])];

const grupos = {
  'DESTAQUE': [],
  'SAUDÁVEL': [],
  'OBSERVAR': [],
  'ATENÇÃO': [],
  'DADOS INSUFICIENTES': []
};

for (const registro of registros) {
  const classe = registro['CLASSIFICACAO GESTOR'];
  if (grupos[classe]) grupos[classe].push(registro);
}

// Ordenação interna: maior score nos positivos, menor score em atenção.
grupos['DESTAQUE'].sort((a, b) => numero(b['SCORE TECNICO']) - numero(a['SCORE TECNICO']));
grupos['SAUDÁVEL'].sort((a, b) => numero(b['SCORE TECNICO']) - numero(a['SCORE TECNICO']));
grupos['OBSERVAR'].sort((a, b) => numero(a['SCORE TECNICO']) - numero(b['SCORE TECNICO']));
grupos['ATENÇÃO'].sort((a, b) => numero(a['SCORE TECNICO']) - numero(b['SCORE TECNICO']));

const blocos = [];

blocos.push(
  `PAINEL META ADS — ${dados.data_referencia || 'sem data'}\n` +
  `Investimento: ${dinheiro(dados.investimento_total)}\n` +
  `Conversas: ${numero(dados.conversas_iniciadas)}\n` +
  `Custo médio/conversa: ${dinheiro(dados.custo_medio_por_conversa)}\n` +
  `Score técnico médio: ${dados.score_tecnico_medio ?? '—'}`
);

function adicionarGrupo(titulo, lista, limite = 3) {
  if (!lista.length) return;

  const itens = lista.slice(0, limite).map((registro, indice) =>
    `${indice + 1}. ${linha(registro)}`
  );

  blocos.push(`${titulo}\n${itens.join('\n\n')}`);
}

adicionarGrupo('DESTAQUES', grupos['DESTAQUE']);
adicionarGrupo('ATENÇÃO', grupos['ATENÇÃO']);
adicionarGrupo('OBSERVAR', grupos['OBSERVAR']);
adicionarGrupo('SAUDÁVEIS', grupos['SAUDÁVEL']);
adicionarGrupo('DADOS INSUFICIENTES', grupos['DADOS INSUFICIENTES']);

// Define a prioridade do dia sem executar nenhuma alteração automática.
let foco = 'Continuar coleta e monitoramento.';
if (grupos['ATENÇÃO'].length) {
  foco = `Revisar primeiro: ${grupos['ATENÇÃO'][0]['NOME OBJETO GESTOR']}.`;
} else if (grupos['DESTAQUE'].length) {
  foco = `Melhor oportunidade atual: ${grupos['DESTAQUE'][0]['NOME OBJETO GESTOR']}. Manter e acumular evidência para futura decisão de escala.`;
}

blocos.push(`FOCO DO GESTOR\n${foco}`);

const mensagem = blocos.join('\n\n');

return [{
  json: {
    ...dados,
    painel_gestor: {
      destaques: grupos['DESTAQUE'],
      saudaveis: grupos['SAUDÁVEL'],
      observar: grupos['OBSERVAR'],
      atencao: grupos['ATENÇÃO'],
      dados_insuficientes: grupos['DADOS INSUFICIENTES'],
      foco_do_gestor: foco
    },
    mensagem_gestor: mensagem
  }
}];

// Divide mensagens longas para respeitar o limite prático do Telegram.
const texto = String($json.mensagem_gestor || '').trim();
if (!texto) return [];

const LIMITE = 3500;
const partes = [];
let atual = '';

for (const bloco of texto.split('\n\n')) {
  const candidato = atual ? `${atual}\n\n${bloco}` : bloco;

  if (candidato.length <= LIMITE) {
    atual = candidato;
    continue;
  }

  if (atual) partes.push(atual);
  atual = bloco;
}

if (atual) partes.push(atual);

return partes.map((parte, indice) => ({
  json: {
    ...$json,
    parte: indice + 1,
    total_partes: partes.length,
    mensagem_envio: partes.length > 1
      ? `Parte ${indice + 1}/${partes.length}\n\n${parte}`
      : parte
  }
}));
